def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The largest color is the surrounding background; zero marks the destination.
    counts = {}
    for row in grid:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    dest = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    if not dest:
        return out
    r0, r1 = min(r for r, c in dest), max(r for r, c in dest)
    c0, c1 = min(c for r, c in dest), max(c for r, c in dest)

    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, 0)]
    a0, a1 = min(r for r, c in obj), max(r for r, c in obj)
    b0, b1 = min(c for r, c in obj), max(c for r, c in obj)

    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            sr, sc = a0 + r - r0, b1 - (c - c0)
            if sr <= a1 and sc >= b0:
                out[r][c] = grid[sr][sc]
    return out
